function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'FrontMiddleBackQueue' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with FrontMiddleBackQueue().';
  if (operations.length - 1 > 1000) return 'At most 1000 calls after the constructor.';
  const pushes = ['pushFront', 'pushMiddle', 'pushBack'];
  const pops = ['popFront', 'popMiddle', 'popBack'];
  for (let i = 1; i < operations.length; i++) {
    if (!Array.isArray(args[i])) return 'Each call needs an argument list.';
    if (pushes.includes(operations[i])) {
      const val = args[i][0];
      if (args[i].length !== 1 || !Number.isInteger(val) || val < 1 || val > 1e9) return 'Push calls take one val from 1 to 10^9.';
    } else if (pops.includes(operations[i])) {
      if (args[i].length !== 0) return 'Pop calls take no arguments.';
    } else {
      return 'Unknown operation: ' + operations[i] + '.';
    }
  }
  return null;
}

