class FrontMiddleBackQueue {
  constructor() {
    this.front = [];
    this.back = [];
  }

  balance() {
    if (this.front.length > this.back.length + 1) {
      this.back.unshift(this.front.pop());
    } else if (this.back.length > this.front.length) {
      this.front.push(this.back.shift());
    }
  }

  pushFront(val) {
    this.front.unshift(val);
    this.balance();
  }

  pushMiddle(val) {
    if (this.front.length > this.back.length) {
      this.back.unshift(this.front.pop());
    }
    this.front.push(val);
  }

  pushBack(val) {
    this.back.push(val);
    this.balance();
  }

  popFront() {
    if (this.front.length === 0) {
      return -1;
    }
    const val = this.front.shift();
    this.balance();
    return val;
  }

  popMiddle() {
    if (this.front.length === 0) {
      return -1;
    }
    const val = this.front.pop();
    this.balance();
    return val;
  }

  popBack() {
    if (this.front.length === 0) {
      return -1;
    }
    const val = this.back.length > 0 ? this.back.pop() : this.front.pop();
    this.balance();
    return val;
  }
}

