function generate(rand, size) {
  const calls = size === 'large' ? 499 : 1 + Math.floor(rand() * 15);
  const maxVal = size === 'large' ? 1e9 : 9;
  // How often to push rather than pop; varying it gives both long queues and many pops on an empty one.
  const pushRate = size === 'large' ? 0.45 + rand() * 0.3 : 0.3 + rand() * 0.5;
  const pushes = ['pushFront', 'pushMiddle', 'pushBack'];
  const pops = ['popFront', 'popMiddle', 'popBack'];
  const operations = ['FrontMiddleBackQueue'];
  const args = [[]];
  for (let i = 0; i < calls; i++) {
    if (rand() < pushRate) {
      operations.push(pushes[Math.floor(rand() * 3)]);
      args.push([1 + Math.floor(rand() * maxVal)]);
    } else {
      operations.push(pops[Math.floor(rand() * 3)]);
      args.push([]);
    }
  }
  return [operations, args];
}
